package codegen

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"strconv"
	"strings"
)

// SlimHeader is added to every file Slim rewrites.
const SlimHeader = "// Post-processed by tools/sfcgen (slim): custom nested object types removed; schema only.\n"

// Slim rewrites a file generated by tfplugingen-framework so that it contains
// only the schema function.
//
// tfplugingen-framework v0.4 also emits a model struct and a custom
// Type/Value pair for every nested attribute, named after the attribute
// alone. Two nested attributes with the same name in one resource (SF
// Compute's order has allocation_schedule_delta both at the top level and
// inside each fill) produce duplicate Go declarations that do not compile.
// The generic runtime works on raw Terraform values and never uses the
// models or custom types, and the framework derives nested object types
// itself when CustomType is unset, so Slim drops the custom types, every
// declaration except the *Schema function, and the imports left unused.
func Slim(src []byte) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "gen.go", src, parser.ParseComments)
	if err != nil {
		return nil, err
	}
	var keep []ast.Decl
	var schemaFuncs int
	for _, d := range f.Decls {
		switch d := d.(type) {
		case *ast.GenDecl:
			if d.Tok == token.IMPORT {
				keep = append(keep, d)
			}
		case *ast.FuncDecl:
			if d.Recv == nil && strings.HasSuffix(d.Name.Name, "Schema") {
				stripCustomTypes(d)
				keep = append(keep, d)
				schemaFuncs++
			}
		}
	}
	if schemaFuncs != 1 {
		return nil, fmt.Errorf("expected exactly one schema function, found %d", schemaFuncs)
	}
	f.Decls = keep
	// Comments attached to removed declarations would otherwise float
	// around; generated files only carry the header comment.
	var comments []*ast.CommentGroup
	for _, cg := range f.Comments {
		if cg.Pos() < f.Package {
			comments = append(comments, cg)
		}
	}
	f.Comments = comments
	removeUnusedImports(f)

	var buf bytes.Buffer
	if err := format.Node(&buf, fset, f); err != nil {
		return nil, err
	}
	out := buf.Bytes()
	// Insert the slim note after the first ("Code generated ...") line.
	if i := bytes.IndexByte(out, '\n'); i >= 0 {
		out = append(append(append([]byte{}, out[:i+1]...), SlimHeader...), out[i+1:]...)
	}
	return format.Source(out)
}

func stripCustomTypes(fn *ast.FuncDecl) {
	ast.Inspect(fn, func(n ast.Node) bool {
		cl, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		elts := cl.Elts[:0]
		for _, e := range cl.Elts {
			if kv, ok := e.(*ast.KeyValueExpr); ok {
				if id, ok := kv.Key.(*ast.Ident); ok && id.Name == "CustomType" {
					continue
				}
			}
			elts = append(elts, e)
		}
		cl.Elts = elts
		return true
	})
}

func removeUnusedImports(f *ast.File) {
	used := map[string]bool{}
	ast.Inspect(f, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok {
				used[id.Name] = true
			}
		}
		return true
	})
	for _, d := range f.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		specs := gd.Specs[:0]
		for _, s := range gd.Specs {
			is := s.(*ast.ImportSpec)
			path, _ := strconv.Unquote(is.Path.Value)
			name := path[strings.LastIndex(path, "/")+1:]
			if is.Name != nil {
				name = is.Name.Name
			}
			if used[name] || name == "_" {
				specs = append(specs, s)
			}
		}
		gd.Specs = specs
	}
	f.Imports = nil
	for _, d := range f.Decls {
		if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			for _, s := range gd.Specs {
				f.Imports = append(f.Imports, s.(*ast.ImportSpec))
			}
		}
	}
}
